// Rebuild a valid RFC822 message from the parsed IMAP item.
//
// Why: the Email Trigger (IMAP) node in n8n-nodes-base 2.38.2 fetches
// BODY.PEEK[TEXT] for format "raw" (headers are lost) and decodes the stream as
// UTF-8, so its "raw" field is neither the original message nor base64url.
// Gmail users.messages.import needs the RFC822 source, so the message is
// rebuilt here from the headers, text/html body and binary attachments that
// the "resolved" format provides.
const cfg = $('Config').first().json;

const STRUCTURAL = new Set([
  'content-type',
  'content-transfer-encoding',
  'content-length',
  'content-disposition',
  'content-id',
  'mime-version',
]);
const BROKEN_AUTH = new Set([
  'dkim-signature',
  'arc-seal',
  'arc-message-signature',
  'arc-authentication-results',
  'authentication-results',
  'received-spf',
]);

const CRLF = '\r\n';

function base64Lines(buf) {
  return Buffer.from(buf).toString('base64').replace(/(.{76})/g, '$1' + CRLF);
}

function contentParam(name, value) {
  if (/^[\x20-\x7e]*$/.test(value)) {
    return `${name}="${value.replace(/(["\\])/g, '\\$1')}"`;
  }
  const encoded = encodeURIComponent(value).replace(
    /['()*!~]/g,
    (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase(),
  );
  return `${name}*=UTF-8''${encoded}`;
}

// Stable, dependency-free content hash used only when a message has no
// Message-ID (the Code node cannot require("crypto")).
function fnv1a64(str) {
  let hash = 0xcbf29ce484222325n;
  const prime = 0x100000001b3n;
  const mask = 0xffffffffffffffffn;
  for (let i = 0; i < str.length; i++) {
    hash ^= BigInt(str.charCodeAt(i));
    hash = (hash * prime) & mask;
  }
  return hash.toString(16).padStart(16, '0');
}

function newBoundary(tag, index) {
  return `=_n8n_${tag}_${Date.now().toString(36)}_${index}`;
}

function textEntity(subtype, content) {
  return {
    headers: [
      `Content-Type: text/${subtype}; charset=utf-8`,
      'Content-Transfer-Encoding: base64',
    ],
    body: base64Lines(Buffer.from(content, 'utf8')) + CRLF,
    children: null,
  };
}

function attachmentEntity(attachment) {
  const contentType = attachment.contentType || 'application/octet-stream';
  return {
    headers: [
      `Content-Type: ${contentType}; ${contentParam('name', attachment.filename)}`,
      `Content-Disposition: attachment; ${contentParam('filename', attachment.filename)}`,
      'Content-Transfer-Encoding: base64',
    ],
    body: base64Lines(attachment.buffer) + CRLF,
    children: null,
  };
}

function multipartEntity(subtype, children, boundary) {
  return {
    headers: [
      `Content-Type: multipart/${subtype}; boundary="${boundary}"`,
      'MIME-Version: 1.0',
    ],
    body: null,
    children,
    boundary,
  };
}

function renderBody(entity) {
  if (!entity.children) return entity.body;
  let out = '';
  for (const child of entity.children) {
    out += `--${entity.boundary}${CRLF}`;
    out += child.headers.join(CRLF) + CRLF + CRLF;
    out += renderBody(child) + CRLF;
  }
  out += `--${entity.boundary}--${CRLF}`;
  return out;
}

async function build(itemIndex, item) {
  const json = item.json || {};
  const headerMap = json.headers || {};

  // Preserve the original header lines and order; the map already collapses
  // duplicate names (e.g. several Received lines), which cannot be recovered.
  const headerLines = [];
  let hasMimeVersion = false;
  for (const [name, line] of Object.entries(headerMap)) {
    const lower = String(name).toLowerCase();
    if (lower === 'mime-version') hasMimeVersion = true;
    if (STRUCTURAL.has(lower)) continue;
    if (cfg.stripBrokenAuthHeaders && BROKEN_AUTH.has(lower)) continue;
    if (typeof line === 'string' && line.trim() !== '') headerLines.push(line);
  }

  const messageIdRaw = json.messageId || headerMap['message-id'] || '';
  const messageId = String(messageIdRaw).replace(/^message-id:\s*/i, '').trim();
  const subject = typeof json.subject === 'string' ? json.subject : '';
  const sender =
    json.from && json.from.text ? String(json.from.text) : String(headerMap.from || '');

  const children = [];
  const text = typeof json.text === 'string' ? json.text : '';
  const html = typeof json.html === 'string' ? json.html : '';
  const bodyParts = [];
  if (text !== '') bodyParts.push(textEntity('plain', text));
  if (html !== '') bodyParts.push(textEntity('html', html));
  if (bodyParts.length === 0) bodyParts.push(textEntity('plain', ''));
  if (bodyParts.length === 1) {
    children.push(bodyParts[0]);
  } else {
    children.push(multipartEntity('alternative', bodyParts, newBoundary('alt', itemIndex)));
  }

  const binary = item.binary || {};
  const attachmentSignature = [];
  for (const key of Object.keys(binary)) {
    const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, key);
    const meta = binary[key] || {};
    const filename = meta.fileName || `${key}.bin`;
    children.push(
      attachmentEntity({
        buffer,
        filename,
        contentType: meta.mimeType,
      }),
    );
    attachmentSignature.push(`${filename}:${buffer.length}`);
  }
  const attachmentCount = attachmentSignature.length;

  const top =
    children.length === 1 && attachmentCount === 0
      ? children[0]
      : multipartEntity('mixed', children, newBoundary('mix', itemIndex));

  const outHeaders = [...headerLines];
  if (!hasMimeVersion) outHeaders.push('MIME-Version: 1.0');
  outHeaders.push(...top.headers);

  const message = outHeaders.join(CRLF) + CRLF + CRLF + renderBody(top);
  const buffer = Buffer.from(message, 'utf8');

  // The fallback hash must not depend on the random MIME boundaries, so it is
  // built from the stable message content only.
  const fallbackSeed = [
    String(json.date || ''),
    sender,
    subject,
    text,
    html,
    attachmentSignature.join('|'),
  ].join('\u0000');
  const key = messageId !== '' ? messageId.toLowerCase() : `sha:${fnv1a64(fallbackSeed)}`;

  return {
    // The IMAP uid is needed downstream to delete the GMX copy after the
    // import has been confirmed (the Gmail API works with its own ids).
    sourceUid:
      json.attributes && json.attributes.uid !== undefined
        ? String(json.attributes.uid)
        : '',
    messageKey: key,
    messageId,
    subject,
    sender,
    mailDate: json.date instanceof Date ? json.date.toISOString() : String(json.date || ''),
    sizeBytes: buffer.length,
    attachmentCount,
    headerCount: outHeaders.length,
    importedFrom: `imap:${cfg.gmxMailbox || 'INBOX'}`,
    rawB64: buffer
      .toString('base64')
      .replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=+$/, ''),
  };
}

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  // pairedItem is set explicitly: downstream nodes read $('Build RFC822').item,
  // which would otherwise depend on n8n's automatic pairing.
  results.push({ json: await build.call(this, i, items[i]), pairedItem: { item: i } });
}
return results;

// One summary row per execution so a failed import becomes a red execution
// instead of a green one with hidden errors.
// Status comes from the Data Table nodes, not from $input: the delete node in
// between only carries {uid, deleted}.
function rowsOf(name) {
  try {
    return $(name).all().map((item) => item.json || {});
  } catch {
    return [];
  }
}
const rows = [...rowsOf('Mark imported'), ...rowsOf('Mark failed')];
const imported = rows.filter((r) => r.status === 'imported').length;
const failed = rows.filter((r) => r.status === 'failed').length;
const failedKeys = rows
  .filter((r) => r.status === 'failed')
  .map((r) => r.messageKey || r.messageId || 'unknown');

return [
  {
    json: {
      total: rows.length,
      imported,
      failed,
      failedKeys,
    },
  },
];

// GMX cleanup failed: the mail is already in Gmail, but the GMX copy stays.
// Make it a red execution so the leftover is visible instead of silent.
const rows = [];
for (const item of $input.all()) {
  const e = item.json?.error;
  const msg =
    typeof e === 'string'
      ? e
      : e?.message || e?.description || e?.error?.message || JSON.stringify(e ?? {});
  const ref = item.json?.messageKey || item.json?.messageId || item.json?.uid || 'unknown';
  rows.push(`${ref}: ${msg}`);
}
throw new Error('GMX-Loeschung fehlgeschlagen: ' + rows.join(' | '));
